mapper.select:
SELECT r.id,r.refund_no,r.order_no,r.amount,r.currency,r.status,r.approval_ref,r.approval_deadline,r.version,r.business_no,
  o.business_no AS order_business_no,r.approval_business_no
FROM tc_refund r JOIN tc_order o ON o.tenant_id=r.tenant_id AND o.id=r.order_id
WHERE r.tenant_id=#{tenant} AND r.status=#{status} AND r.id > #{after}
ORDER BY r.id LIMIT #{limit}
